-- Each person's due-total for a closed period, fixed when it closed: the dues of their claims that count dated
-- in it. A person with none has no line, and shows 0.00. Reopening the period removes its lines.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    total     DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- A soft-closed period has its due-totals fixed like a closed one, but claims dated in it can still change.
ALTER TABLE period ADD COLUMN soft BOOLEAN DEFAULT FALSE NOT NULL;
-- Whether the claim was added while the period it is dated in was soft-closed.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
-- A period can be closed: its due-total is then fixed at what it was when it closed, and no claim dated in it
-- can change.
ALTER TABLE period ADD COLUMN closed       BOOLEAN       DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(19, 2);
